insert into public.products (id, store_id, inventory_code, slug, title_ka, title_en, title_ru, description_ka, description_en, description_ru, category_id, condition, status, price, quantity, oem_number, featured, created_at, updated_at) values ('e0000000-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111111', 'AP-00001', 'toyota-camry-xv70-front-headlight-left-ap-00001', 'წინა ფარი მარცხენა — Toyota Camry XV70', 'Front headlight, left — Toyota Camry XV70', 'Фара передняя левая — Toyota Camry XV70', 'ორიგინალი ნაწილი — წინა ფარი მარცხენა, მოხსნილი Toyota Camry XV70 (2017–2024)-დან. შემოწმებულია და მზადაა დასაყენებლად. მდგომარეობა — თითქმის ახალი. ფოტოებზე ნაჩვენებია რეალური ნაწილი. ნახვა შესაძლებელია ჩვენს მაღაზიაში თბილისში.', 'Genuine front headlight, left removed from a Toyota Camry XV70 (2017–2024). Inspected and ready to fit. Condition is close to new. Photos show the actual part. You can view it at our shop in Tbilisi.', 'Оригинальная деталь — фара передняя левая, снята с Toyota Camry XV70 (2017–2024). Проверена и готова к установке. Состояние — почти новое. На фото — реальная деталь. Можно осмотреть в нашем магазине в Тбилиси.', 'c0000000-0000-4000-8000-000000000001', 'like_new', 'available', 260, 1, '81150-ST', true, '2026-10-30T04:42:00.000Z', '2026-10-30T04:42:00.000Z') on conflict (id) do nothing;
